const CACHE='cookxuan-mobile-20261110-v6';
const SHELL=['./','./index.html','./app.css','./claude.css?v=5','./book.css?v=5','./refined.css?v=6','./readability.js?v=5','./app.js?v=5','./catalog.js','./manifest.webmanifest','./assets/favicon.svg','./assets/hero.webp','./assets/dishes.webp','./assets/steps-noodles.webp','./assets/icon-180.png','./assets/icon-192.png','./assets/icon-512.png','./prototypes/index.html','./prototypes/design.css?v=5','./prototypes/design.js?v=5'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('cookxuan-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==self.location.origin)return;if(req.mode==='navigate'){event.respondWith(fetch(req).then(response=>{if(response.ok&&response.type!=='opaqueredirect'){const clone=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(req,clone)));}return response;}).catch(async()=>await caches.match(req)||await caches.match(url.pathname.includes('/prototypes')?'./prototypes/index.html':'./index.html')));return;}event.respondWith(caches.match(req).then(cached=>{const update=fetch(req).then(response=>{if(response.ok)event.waitUntil(caches.open(CACHE).then(cache=>cache.put(req,response.clone())));return response;});if(cached){event.waitUntil(update.catch(()=>{}));return cached;}return update;}));});
